def is_safe(board, row, col, n):
    for i in range(row):
        if board[i] == col or board[i] - i == col - row or board[i] + i == col + row:
            return False
    return True

def solve_nqueens_util(board, row, n, fixed):
    if row == n:
        return True
    if row in fixed:
        col = fixed[row]
        if is_safe(board, row, col, n):
            board[row] = col
            if solve_nqueens_util(board, row + 1, n, fixed):
                return True
            board[row] = -1
        return False
    for col in range(n):
        if is_safe(board, row, col, n):
            board[row] = col
            if solve_nqueens_util(board, row + 1, n, fixed):
                return True
            board[row] = -1
    return False

def solve_nqueens(n, fixed):
    board = [-1] * n
    if solve_nqueens_util(board, 0, n, fixed):
        return board
    return None

fixed = {1: 12, 11: 1}
solution = solve_nqueens(13, fixed)
print(solution)

def check_solution(board, n):
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j] or abs(board[i] - board[j]) == abs(i - j):
                return False
    return True

sol = [0, 12, 3, 7, 10, 4, 2, 9, 11, 6, 8, 1, 5]
print(check_solution(sol, 13))
print(len(set(sol)) == 13)
